import re
p='llm/deltanet.go'
s=open(p).read()
old='''// softplus is ggml's, cutoff and all: above 20 the exponential overflows
// nothing but the answer is x to the last bit anyway.
func softplus(x float32) float32 {
	if x > 20 {
		return x
	}
	return float32(math.Log1p(math.Exp(float64(x))))
}'''
new='''// softplus is ggml's, cutoff and all — including the part that looks like a
// bug and is load-bearing. `logf(1.0f + expf(x))` adds in **float32**, so
// every x below about -16.6 flushes to exactly zero rather than to exp(x),
// and `a_softplus-0` has one such zero among its 336 values. math.Log1p
// would return 2e-09 there and be wrong about the reference.
func softplus(x float32) float32 {
	if x > 20 {
		return x
	}
	return float32(math.Log(float64(1 + float32(math.Exp(float64(x))))))
}'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
