1	// Package llm is the qwen3.8-flash-next vertical: the model LLM.md builds,
2	// CPU reference first and then on the GPU, the same order every other
3	// vertical in this repo took.
4	//
5	// The oracle here is llama.cpp rather than a Python dump (LLM.md D5). Its own
6	// graph callback writes every intermediate tensor of a real forward pass to
7	// `reference/out/llm/` via `reference/eval_dump.c`, and the tests in this
8	// package read those files back and compare value for value. So "correct"
9	// means "the reference implementation's own numbers", not "a second reading
10	// of the paper".
11	package llm
12	
13	import (
14		"encoding/binary"
15		"fmt"
16		"math"
17		"os"
18		"path/filepath"
19		"sort"
20		"strings"
21	)
22	
23	// A Dump is one tensor recorded by reference/eval_dump.c: the reference
24	// implementation's value for a named node of a real forward pass.
25	//
26	// Shape is ggml's, so NE[0] is the fastest-varying axis. Values is the
27	// payload converted to float32 and laid out in that same order, which means
28	// a ggml [features, tokens] tensor reads back as tokens-major rows of
29	// features — the layout the rest of this package uses.
30	type Dump struct {
31		Name string
32		Op   string
33		Seq  int // graph order, from the filename
34		NE   [4]int64
35		NB   [4]uint64
36		Vals []float32
37		// Ints is the payload of an integer tensor, which is what the QSA
38		// indexer's top-k selection is. Vals carries the same values widened, so
39		// a shape check does not have to know which kind it is.
40		Ints  []int32
41		GType uint32
42	}
43	
44	// Rows is the product of every axis but the first: how many NE[0]-long rows
45	// Values holds.
46	func (d *Dump) Rows() int {
47		n := int64(1)
48		for _, v := range d.NE[1:] {
49			if v > 0 {
50				n *= v
51			}
52		}
53		return int(n)
54	}
55	
56	// Row returns row i, of NE[0] values.
57	func (d *Dump) Row(i int) []float32 {
58		w := int(d.NE[0])
59		return d.Vals[i*w : (i+1)*w]
60	}
