162	
163	// dumpTypeSize is the byte width of every ggml type the trace carries.
164	var dumpTypeSize = map[uint32]int{0: 4, 1: 2, 26: 4, 30: 2}
165	
166	// contiguous reports whether the payload can be read as a flat array — which
167	// is true of every dumped tensor that is not a strided view.
168	func (d *Dump) contiguous(tsz int) bool {
169		stride := uint64(tsz)
170		for ax := 0; ax < 4; ax++ {
171			if d.NB[ax] != stride {
172				return false
173			}
174			if d.NE[ax] > 0 {
175				stride *= uint64(d.NE[ax])
176			}
177		}
178		return true
179	}
180	
181	func f16(u uint16) float32 {
182		sign := uint32(u&0x8000) << 16
183		exp := int32(u>>10) & 0x1f
184		man := uint32(u & 0x3ff)
185		switch {
186		case exp == 0:
187			if man == 0 {
188				return math.Float32frombits(sign)
189			}
190			e := int32(-1)
191			for man&0x400 == 0 {
192				man <<= 1
193				e--
194			}
195			man &= 0x3ff
196			return math.Float32frombits(sign | uint32(127-15+e+1)<<23 | man<<13)
197		case exp == 0x1f:
198			return math.Float32frombits(sign | 0xff<<23 | man<<13)
199		default:
200			return math.Float32frombits(sign | uint32(exp-15+127)<<23 | man<<13)
201		}
202	}
203	
204	// A Trace is a whole dumped forward pass, indexed by name. A name can repeat
205	// — `build_hc_mix` runs twice a layer — so the entries are the writes in
206	// graph order and lookup takes an occurrence.
207	type Trace struct {
208		Dir     string
209		Entries []string // file paths in graph order
210		byName  map[string][]string
211	}
212	
213	// OpenTrace indexes a directory written by reference/eval_dump.c without
214	// reading the payloads.
215	func OpenTrace(dir string) (*Trace, error) {
216		names, err := filepath.Glob(filepath.Join(dir, "*.bin"))
217		if err != nil {
218			return nil, err
219		}
220		if len(names) == 0 {
221			return nil, fmt.Errorf("%s: no eval_dump files (run reference/eval_dump.c)", dir)
222		}
223		sort.Strings(names)
224		t := &Trace{Dir: dir, byName: map[string][]string{}}
225		for _, p := range names {
226			base := filepath.Base(p)
227			if base == "tokens.bin" {
228				continue
229			}
